private val Light = YBPalette(Color(0xFFF2F7F4), Color.White, Color(0xFFE8F2ED), Color(0xFF08241C), Color(0xFF71847C), Color(0xFF16C98A), Color(0xFFC9F8E1), Color(0xFFFFC857), Color(0xFFE65353), Color(0xFFDCEAE4))
private val Dark = YBPalette(Color(0xFF061512), Color(0xFF0D211C), Color(0xFF133129), Color(0xFFF2FBF7), Color(0xFF9AB3A9), Color(0xFF24D995), Color(0xFF163D31), Color(0xFFFFC857), Color(0xFFFF6B6B), Color(0xFF23483D))

@Composable
fun YurdunuBilModernApp() {
    val context = LocalContext.current
    val prefs = remember { context.getSharedPreferences("yurdunu_bil_native", 0) }
    var darkMode by remember { mutableStateOf(prefs.getBoolean("dark_theme", false)) }
    val p = if (darkMode) Dark else Light
    var tab by rememberSaveable { mutableIntStateOf(0) }
    var studyTopic by remember { mutableStateOf<Topic?>(null) }
    var province by remember { mutableStateOf<Province?>(null) }
    var quiz by remember { mutableStateOf<List<Question>?>(null) }
    var quizTitle by remember { mutableStateOf("") }
    var arenaFocus by rememberSaveable { mutableStateOf(false) }
    val holder = rememberSaveableStateHolder()

    fun launchQuiz(title: String, mode: SharedGameMode) {
        val picked = SharedQuestionPool.pick(mode)
        if (picked.isNotEmpty()) { quizTitle = title; quiz = picked; prefs.edit().putString("last_activity", title).apply() }
    }

    BackHandler(enabled = studyTopic != null || province != null || quiz != null || tab != 0) {
        when { quiz != null -> quiz = null; studyTopic != null -> studyTopic = null; province != null -> province = null; tab != 0 -> tab = 0 }
    }

    if (studyTopic != null) {
        val selectedTopic = studyTopic!!
        DeepLessonScreen(selectedTopic, p, prefs, onBack = { studyTopic = null }) {
            val title = selectedTopic.title
            studyTopic = null
            launchQuiz(title, SharedGameMode("study-$title", title, selectedTopic.subtitle, selectedTopic.icon, 10, 180, 100, SharedQuestionPool.topicForLibrary(title)))
        }
        return
    }
    if (province != null) { ProvinceDetailModern(province!!, p) { province = null }; return }
    if (quiz != null) { QuizModern(quizTitle, quiz!!, p, prefs) { quiz = null }; return }

    MaterialTheme(colorScheme = if (darkMode) darkColorScheme(primary = p.green, background = p.bg, surface = p.card, onSurface = p.text) else lightColorScheme(primary = p.green, background = p.bg, surface = p.card, onSurface = p.text)) {
        Scaffold(containerColor = p.bg, bottomBar = {
            NavigationBar(containerColor = p.card, tonalElevation = 8.dp) {
                val nav = listOf("Ana Sayfa" to Icons.Default.Home, "Kütüphane" to Icons.Default.MenuBook, "Etkinlikler" to Icons.Default.SportsEsports, "Ayarlar" to Icons.Default.Settings)
                nav.forEachIndexed { i, item -> NavigationBarItem(selected = tab == i, onClick = { tab = i; if (i != 2) arenaFocus = false }, icon = { Icon(item.second, item.first) }, label = { Text(item.first, fontSize = 10.sp) }, colors = NavigationBarItemDefaults.colors(selectedIconColor = p.text, selectedTextColor = p.text, indicatorColor = p.green.copy(alpha = .18f), unselectedIconColor = p.muted, unselectedTextColor = p.muted)) }
            }
        }) { padding ->
            Box(Modifier.fillMaxSize().padding(padding)) {
                holder.SaveableStateProvider("tab-$tab") {
                    when (tab) {
                        0 -> HomeModern(p, prefs, { launchQuiz("Hızlı 10", SharedGameModes.quick) }) { arenaFocus = true; tab = 2 }
                        1 -> LibraryModern(p, { studyTopic = it }, { province = it })
                        2 -> EventsModern(p, arenaFocus) { launchQuiz(it.title, it) }
                        else -> SettingsModern(p, prefs, darkMode) { value -> darkMode = value; prefs.edit().putBoolean("dark_theme", value).apply() }
                    }
                }
            }
        }
    }
}

@Composable private fun HomeModern(p: YBPalette, prefs: SharedPreferences, onQuick: () -> Unit, onArena: () -> Unit) {
    val list = rememberLazyListState(); val solved = prefs.getInt("solved", 0); val correct = prefs.getInt("correct", 0); val xp = prefs.getInt("xp", 0); val streak = prefs.getInt("streak", 0); val accuracy = if (solved == 0) 0 else (correct * 100f / solved).roundToInt()
    LazyColumn(state = list, contentPadding = PaddingValues(bottom = 24.dp), verticalArrangement = Arrangement.spacedBy(13.dp)) {
        item { Box(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(Color(0xFF06241C), Color(0xFF0A4A39), Color(0xFF0D7253))), RoundedCornerShape(bottomStart = 32.dp, bottomEnd = 32.dp)).statusBarsPadding().padding(22.dp)) { Column { Row(verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("Yurdunu Bil", color = Color.White, fontSize = 29.sp, fontWeight = FontWeight.Black); Text("KPSS Önlisans • Türkiye Coğrafyası", color = p.mint, fontSize = 11.sp) }; Surface(shape = RoundedCornerShape(12.dp), color = Color.White.copy(alpha = .1f)) { Text("Lv.${1 + xp / 500}", color = Color.White, fontWeight = FontWeight.Black, modifier = Modifier.padding(10.dp)) } }; Spacer(Modifier.height(18.dp)); Text("Bugün Türkiye'yi biraz daha çöz. ✨", color = Color.White, fontSize = 21.sp, fontWeight = FontWeight.ExtraBold); Spacer(Modifier.height(13.dp)); Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { Stat("$solved", "SORU"); Stat("$xp", "XP"); Stat("$streak", "SERİ") } } } }
        item { ModernCard(p, Modifier.padding(horizontal = 16.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Text("🎯", fontSize = 34.sp); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Eyebrow("BUGÜNÜN GÖREVİ", p.green); Text(SharedQuestionPool.dailyMode().title, color = p.text, fontSize = 20.sp, fontWeight = FontWeight.Black); Text("Kısa bir coğrafya turuyla ritmini koru.", color = p.muted, fontSize = 12.sp) } }; Spacer(Modifier.height(12.dp)); Primary("Başla • 10 Soru", p, onQuick) } }
        item { Row(Modifier.padding(horizontal = 16.dp), horizontalArrangement = Arrangement.spacedBy(10.dp)) { Mini(p, "⚡", "Hızlı 10", "10 soru", onQuick, Modifier.weight(1f)); Mini(p, "🔥", "Bilgi Zinciri", "Serini büyüt", onQuick, Modifier.weight(1f)) } }
        item { ModernCard(p, Modifier.padding(horizontal = 16.dp), true) { Row(verticalAlignment = Alignment.CenterVertically) { Text("⚔️", fontSize = 34.sp); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Eyebrow("ARENA", p.gold); Text("Bilgini sahaya çıkar.", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.Black); Text("1v1 • hız • bölge • Türkiye Ustası", color = Color.White.copy(alpha = .7f), fontSize = 12.sp) } }; Spacer(Modifier.height(12.dp)); Button(onClick = onArena, modifier = Modifier.fillMaxWidth().height(50.dp), shape = RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = p.gold, contentColor = Color(0xFF142117))) { Text("Arena'ya Git", fontWeight = FontWeight.Black) } } }
        item { ModernCard(p, Modifier.padding(horizontal = 16.dp)) { Eyebrow("GELİŞİMİN", p.green); Text("%$accuracy genel doğruluk", color = p.text, fontSize = 21.sp, fontWeight = FontWeight.Black); Text(if (solved == 0) "İlk testini çöz ve ilerlemeni başlat." else "$correct doğru cevapla devam ediyorsun.", color = p.muted, fontSize = 12.sp); Spacer(Modifier.height(10.dp)); LinearProgressIndicator(progress = { accuracy / 100f }, Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(8.dp)), color = p.green, trackColor = p.elevated) } }
        item { ModernCard(p, Modifier.padding(horizontal = 16.dp)) { Eyebrow("DEVAM ET", p.gold); Text(prefs.getString("last_activity", "Henüz çalışma yok") ?: "Henüz çalışma yok", color = p.text, fontSize = 17.sp, fontWeight = FontWeight.Black); Text("Son yaptığın çalışmaya kaldığın yerden devam et.", color = p.muted, fontSize = 12.sp) } }
    }
}

@Composable private fun Stat(v: String, l: String) { Column(Modifier.clip(RoundedCornerShape(13.dp)).background(Color.White.copy(alpha = .09f)).padding(horizontal = 12.dp, vertical = 8.dp)) { Text(v, color = Color.White, fontWeight = FontWeight.Black); Text(l, color = Color.White.copy(alpha = .58f), fontSize = 7.sp) } }
@Composable private fun Eyebrow(t: String, c: Color) { Text(t, color = c, fontSize = 10.sp, fontWeight = FontWeight.Black, letterSpacing = 1.sp) }
@Composable private fun Mini(p: YBPalette, icon: String, title: String, sub: String, click: () -> Unit, mod: Modifier) { ModernCard(p, mod.clickable(onClick = click)) { Text(icon, fontSize = 28.sp); Spacer(Modifier.height(6.dp)); Text(title, color = p.text, fontWeight = FontWeight.Black, fontSize = 15.sp); Text(sub, color = p.green, fontSize = 10.sp, fontWeight = FontWeight.Bold) } }
@Composable private fun ModernCard(p: YBPalette, mod: Modifier = Modifier, dark: Boolean = false, content: @Composable ColumnScope.() -> Unit) { Card(modifier = mod.fillMaxWidth(), shape = RoundedCornerShape(22.dp), elevation = CardDefaults.cardElevation(3.dp), colors = CardDefaults.cardColors(containerColor = if (dark) Color.Transparent else p.card)) { Column(if (dark) Modifier.background(Brush.linearGradient(listOf(Color(0xFF05251D), Color(0xFF0B4B3A))).padding(17.dp) else Modifier.padding(17.dp), content = content) } }
@Composable private fun Primary(t: String, p: YBPalette, click: () -> Unit) { Button(onClick = click, Modifier.fillMaxWidth().height(50.dp), RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = p.green, contentColor = Color(0xFF052219))) { Text(t, fontWeight = FontWeight.Black) } }

@Composable private fun LibraryModern(p: YBPalette, onStudy: (Topic) -> Unit, onProvince: (Province) -> Unit) { var search by rememberSaveable { mutableStateOf("") }; val list = rememberLazyListState(); val topics = GeographyData.topics.filter { it.title.contains(search, true) || it.subtitle.contains(search, true) }; LazyColumn(state = list, contentPadding = PaddingValues(16.dp, 10.dp, 16.dp, 28.dp), verticalArrangement = Arrangement.spacedBy(11.dp)) { item { Text("Kütüphane", color = p.text, fontSize = 29.sp, fontWeight = FontWeight.Black); Text("Önce oku → anla → sonra test et.", color = p.green, fontSize = 12.sp, fontWeight = FontWeight.Bold); Spacer(Modifier.height(8.dp)); OutlinedTextField(search, { search = it }, Modifier.fillMaxWidth(), singleLine = true, shape = RoundedCornerShape(17.dp), label = { Text("Konu ara") }, leadingIcon = { Icon(Icons.Default.Search, null) }, colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = p.green, unfocusedBorderColor = p.line, focusedLabelColor = p.green, cursorColor = p.green, focusedTextColor = p.text, unfocusedTextColor = p.text)) }; item { ModernCard(p, dark = true) { Eyebrow("ÇALIŞMA KÜTÜPHANESİ", p.mint); Text("12 ana konu • derinlemesine çalışma", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.Black); Text("Uzun anlatım, temel kavramlar, sınav tuzakları ve hatırlama kartları.", color = Color.White.copy(alpha = .7f), fontSize = 12.sp, lineHeight = 18.sp) } }; item { Text("Konu Bankası", color = p.text, fontSize = 19.sp, fontWeight = FontWeight.Black) }; items(topics, key = { it.title }) { topic -> ModernCard(p, Modifier.clickable { onStudy(topic) }) { Row(verticalAlignment = Alignment.CenterVertically) { Surface(shape = RoundedCornerShape(15.dp), color = p.elevated) { Text(topic.icon, fontSize = 27.sp, modifier = Modifier.padding(10.dp)) }; Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text(topic.title, color = p.text, fontWeight = FontWeight.Black, fontSize = 16.sp); Text(topic.subtitle, color = p.muted, fontSize = 11.sp, maxLines = 2, overflow = TextOverflow.Ellipsis); Text("Ders sayfasını aç →", color = p.green, fontSize = 10.sp, fontWeight = FontWeight.Bold) }; Icon(Icons.Default.ChevronRight, null, tint = p.green) } } }; item { Spacer(Modifier.height(8.dp)); Text("İl Keşfi", color = p.text, fontSize = 19.sp, fontWeight = FontWeight.Black); Text("İl → bölge → özellik bağlantısını kur.", color = p.muted, fontSize = 11.sp) }; items(GeographyData.provinces, key = { it.name }) { city -> ModernCard(p, Modifier.clickable { onProvince(city) }) { Row(verticalAlignment = Alignment.CenterVertically) { Text("📍", fontSize = 24.sp); Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text(city.name, color = p.text, fontWeight = FontWeight.Black); Text(city.region, color = p.green, fontSize = 10.sp, fontWeight = FontWeight.Bold); Text(city.clue, color = p.muted, fontSize = 10.sp, maxLines = 2, overflow = TextOverflow.Ellipsis) }; Icon(Icons.Default.ChevronRight, null, tint = p.green) } } } } }

@Composable private fun DeepLessonScreen(topic: Topic, p: YBPalette, prefs: SharedPreferences, onBack: () -> Unit, onQuiz: () -> Unit) { val lesson = remember(topic.title) { DeepLibrary.forTopic(topic) }; val scroll = rememberScrollState(); val readSet = prefs.getStringSet("read_topics", emptySet()) ?: emptySet(); val read = topic.title in readSet; Column(Modifier.fillMaxSize().background(p.bg).statusBarsPadding().navigationBarsPadding()) { Row(Modifier.padding(8.dp), verticalAlignment = Alignment.CenterVertically) { IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, "Geri", tint = p.text) }; Column(Modifier.weight(1f)) { Eyebrow("DERS SAYFASI", p.green); Text(topic.title, color = p.text, fontSize = 21.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis) }; Text(topic.icon, fontSize = 21.sp) }; Column(Modifier.fillMaxSize().verticalScroll(scroll).padding(horizontal = 16.dp, vertical = 5.dp)) { ModernCard(p, dark = true) { Text(lesson.title, color = Color.White, fontSize = 24.sp, fontWeight = FontWeight.Black); Text(lesson.subtitle, color = p.mint, fontSize = 12.sp, fontWeight = FontWeight.Bold); Spacer(Modifier.height(10.dp)); Text(lesson.summary, color = Color.White.copy(alpha = .88f), fontSize = 14.sp, lineHeight = 21.sp) }; Spacer(Modifier.height(12.dp)); lesson.sections.forEach { s -> ModernCard(p) { Text(s.title, color = p.text, fontSize = 17.sp, fontWeight = FontWeight.Black); Spacer(Modifier.height(6.dp)); Text(s.body, color = p.muted, fontSize = 13.sp, lineHeight = 20.sp); s.bullets.forEach { b -> Spacer(Modifier.height(6.dp)); Row(verticalAlignment = Alignment.Top) { Text("•", color = p.green, fontWeight = FontWeight.Black); Spacer(Modifier.width(8.dp)); Text(b, color = p.text, fontSize = 12.sp, lineHeight = 18.sp, Modifier.weight(1f)) } } }; Spacer(Modifier.height(11.dp)) }; ModernCard(p) { Row(verticalAlignment = Alignment.Top) { Icon(Icons.Default.Warning, null, tint = p.gold); Spacer(Modifier.width(9.dp)); Column { Eyebrow("ÖSYM / KPSS TUZAĞI", p.gold); Text(lesson.examTrap, color = p.text, fontSize = 13.sp, lineHeight = 20.sp) } } }; Spacer(Modifier.height(11.dp)); ModernCard(p) { Eyebrow("KENDİNİ YOKLA", p.green); lesson.recall.forEachIndexed { i, q -> Spacer(Modifier.height(8.dp)); Text("${i + 1}. $q", color = p.text, fontSize = 13.sp, lineHeight = 19.sp) } }; Spacer(Modifier.height(12.dp)); Button(onClick = { val next = readSet.toMutableSet(); if (!read) next.add(topic.title) else next.remove(topic.title); prefs.edit().putStringSet("read_topics", next).apply() }, Modifier.fillMaxWidth().height(48.dp), RoundedCornerShape(16.dp), colors = ButtonDefaults.buttonColors(containerColor = if (read) p.elevated else p.green, contentColor = if (read) p.text else Color(0xFF052219))) { Icon(if (read) Icons.Default.CheckCircle else Icons.Default.MenuBook, null); Spacer(Modifier.width(7.dp)); Text(if (read) "Konu okundu" else "Bu konuyu okudum", fontWeight = FontWeight.Black) }; Spacer(Modifier.height(9.dp)); Primary("Şimdi Konuyu Test Et", p, onQuiz); Spacer(Modifier.height(22.dp)) } } }

