k = { if (NotificationHelper.canNotify(context)) NotificationHelper.sendTest(context) else if (android.os.Build.VERSION.SDK_INT >= 33) activity?.requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"), 9001) }, Modifier.fillMaxWidth(), RoundedCornerShape(15.dp), colors = ButtonDefaults.outlinedButtonColors(contentColor = p.green)) { Icon(Icons.Default.NotificationsActive, null); Spacer(Modifier.width(7.dp)); Text("Test bildirimi gönder", fontWeight = FontWeight.Bold) } } }; item { ModernCard(p) { Eyebrow("İLERLEME", p.green); Setting("Çözülen soru", prefs.getInt("solved", 0).toString(), p); Setting("Kazanılan XP", prefs.getInt("xp", 0).toString(), p); Setting("Doğru cevap", prefs.getInt("correct", 0).toString(), p); Setting("Yanlış cevap", prefs.getInt("wrong", 0).toString(), p) } }; item { ModernCard(p) { Eyebrow("UYGULAMA", p.gold); Text("Yurdunu Bil • 0.3.0", color = p.text, fontSize = 16.sp, fontWeight = FontWeight.Black); Text("Stabil geri dönüş • kalıcı oturum • derin kütüphane • karanlık tema • bildirimler", color = p.muted, fontSize = 11.sp, lineHeight = 17.sp) } } } }
@Composable private fun Setting(t: String, v: String, p: YBPalette) { Row(Modifier.fillMaxWidth().padding(top = 9.dp), horizontalArrangement = Arrangement.SpaceBetween) { Text(t, color = p.muted, fontSize = 12.sp); Text(v, color = p.text, fontWeight = FontWeight.Black) } }

@Composable private fun QuizModern(title: String, qs: List<Question>, p: YBPalette, prefs: SharedPreferences, onDone: () -> Unit) { var index by rememberSaveable(title) { mutableIntStateOf(0) }; var selected by rememberSaveable(title) { mutableIntStateOf(-1) }; var correct by rememberSaveable(title) { mutableIntStateOf(0) }; var wrong by rememberSaveable(title) { mutableIntStateOf(0) }; var finished by rememberSaveable(title) { mutableStateOf(false) }; val q = qs.getOrNull(index); Column(Modifier.fillMaxSize().background(p.bg).statusBarsPadding().navigationBarsPadding().padding(16.dp)) { if (finished || q == null) { ModernCard(p, dark = true) { Eyebrow("TEST TAMAMLANDI 🎉", p.mint); Text(title, color = Color.White, fontSize = 23.sp, fontWeight = FontWeight.Black); Spacer(Modifier.height(12.dp)); Text("$correct doğru • $wrong yanlış", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Black); Text("${qs.size} soruda %${if (qs.isEmpty()) 0 else (correct * 100f / qs.size).roundToInt()} başarı", color = Color.White.copy(alpha = .72f)); Spacer(Modifier.height(14.dp)); Primary("Devam Et", p, onDone) }; return }; Row(verticalAlignment = Alignment.CenterVertically) { IconButton(onClick = onDone) { Icon(Icons.Default.ArrowBack, "Çık", tint = p.text) }; Column(Modifier.weight(1f)) { Eyebrow(title, p.green); Text("Soru ${index + 1} / ${qs.size}", color = p.text, fontWeight = FontWeight.Black) } }; LinearProgressIndicator(progress = { (index + 1f) / qs.size }, Modifier.fillMaxWidth().height(7.dp).clip(RoundedCornerShape(7.dp)), color = p.green, trackColor = p.elevated); Spacer(Modifier.height(13.dp)); ModernCard(p) { Text(q.text, color = p.text, fontSize = 17.sp, lineHeight = 24.sp, fontWeight = FontWeight.Bold) }; Spacer(Modifier.height(11.dp)); q.options.forEachIndexed { i, option -> val chosen = selected == i; val right = q.correctIndex == i; val bg = when { selected == -1 -> p.card; chosen && right -> p.green.copy(alpha = .18f); chosen && !right -> p.red.copy(alpha = .16f); selected != -1 && right -> p.green.copy(alpha = .12f); else -> p.card }; Card(Modifier.fillMaxWidth().padding(bottom = 8.dp).clickable(enabled = selected == -1) { selected = i; if (right) correct++ else wrong++ }, shape = RoundedCornerShape(17.dp), colors = CardDefaults.cardColors(containerColor = bg)) { Row(Modifier.padding(14.dp), verticalAlignment = Alignment.Top) { Text("${('A'.code + i).toChar()}", color = p.green, fontWeight = FontWeight.Black); Spacer(Modifier.width(10.dp)); Text(option, color = p.text, fontSize = 13.sp, lineHeight = 19.sp, Modifier.weight(1f)) } } }; if (selected != -1) { ModernCard(p) { Eyebrow(if (selected == q.correctIndex) "DOĞRU" else "YANLIŞ", if (selected == q.correctIndex) p.green else p.red); Text(q.explanation, color = p.text, fontSize = 12.sp, lineHeight = 18.sp); Spacer(Modifier.height(9.dp)); Primary(if (index + 1 == qs.size) "Sonucu Gör" else "Sonraki Soru", p) { if (index + 1 == qs.size) { prefs.edit().putInt("solved", prefs.getInt("solved", 0) + qs.size).putInt("correct", prefs.getInt("correct", 0) + correct).putInt("wrong", prefs.getInt("wrong", 0) + wrong).putInt("xp", prefs.getInt("xp", 0) + correct * 10).apply(); finished = true } else { index++; selected = -1 } } } } } }
